package com.worksphere.controller; import com.worksphere.service.NotificationService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService s;public NotificationController(NotificationService x){s=x;} @GetMapping public Object mine(Authentication a){return s.mine(a);} @PutMapping("/{id}/read") public void read(@PathVariable Long id,Authentication a){s.read(id,a);} }
